// Access the input data objects provided to the tool node
const weatherData = $('OpenWeatherMap').item.json;

const temp = weatherData.main.temp;
const feelsLike = weatherData.main.feels_like;
const description = weatherData.weather[0].description;
const humidity = weatherData.main.humidity;

// Returns a clean structured text format for the AI model to interpret
return `Current Weather conditions: ${description}. Temperature: ${temp}°C. Feels like: ${feelsLike}°C. Humidity: ${humidity}%.`;

const items = $input.all();

const audioKeywords = /\b(voice note|voice message|voice reply|audio (file|reply|response|message)|send.*audio|read (that|this) out|speak (it|that)|say (it|that) out loud|reply in audio|reply in voice)\b/i;

const trigger = $('WhatsApp Trigger').item.json.messages?.[0] || {};

let transcribedText = '';
try {
  transcribedText = $('Transcribe a recording').item.json.text || '';
} catch (e) {
  transcribedText = '';
}

const userText = trigger.text?.body || trigger.image?.caption || transcribedText || '';

const askedForAudio = audioKeywords.test(userText);

const replyMode = askedForAudio ? 'AUDIO' : 'TEXT';

for (const item of items) {
  item.json.replyMode = replyMode;
}

return items;
